actions.script:
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
// standalone (fop) path outside the authz filter — scope org explicitly
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def ef = ec.entity.find("zenith.erp.pos.PosStockWastageView").orderBy("-wastageDate").limit(200)
if (_org && _org != '_NA_') ef.condition("organizationPartyId", _org)
def rowsRaw = ef.list()
def reasonNames = [:]
ec.entity.find("moqui.basic.Enumeration").condition("enumTypeId","PosWastageReason").list().each { reasonNames[it.enumId] = it.description }
def zinr = context.zinr
def fmtAmt = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
def fmtQty = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0')) }
entries = rowsRaw.collect { w ->
    [dt: (w.wastageDate ? ec.l10n.format(w.wastageDate, 'dd MMM yyyy hh:mm a') : ''),
     product: (w.productName ?: ''), batch: (w.batchNumber ?: '-'),
     qty: fmtQty(w.quantity), cost: fmtAmt(w.unitCost), loss: fmtAmt(w.totalLoss),
     reason: (reasonNames[w.wastageReason] ?: w.wastageReason ?: ''),
     by: ([(w.firstName ?: ''), (w.lastName ?: '')].findAll{it}.join(' '))] }
def tLoss = rowsRaw.sum { (it.totalLoss ?: 0) as BigDecimal } ?: 0.0G
totLossStr = fmtAmt(tLoss)
entryCountStr = rowsRaw.size().toString()
